module traffic_light (
    input clk,
    input reset,
    input ped,
    output reg [1:0] light,
    output reg walk
);

    reg [2:0] state;
    reg [2:0] next_state;
    reg [2:0] count;

    always @(posedge clk) begin
        if (reset) begin
            state <= 3'd0;
            count <= 3'd0;
            light <= 2'b00;
            walk <= 1'b1;
        end else begin
            if (state == 3'd0) begin
                next_state <= 3'd0;
                count <= 3'd3;
            end else if (state == 3'd1) begin
                next_state <= 3'd1;
                count <= 3'd4;
            end else if (state == 3'd2) begin
                next_state <= 3'd2;
                count <= 3'd2;
            end else if (state == 3'd3) begin
                next_state <= 3'd0;
                count <= 3'd3;
            end else if (state == 3'd4) begin
                next_state <= 3'd1;
                count <= 3'd4;
            end else if (state == 3'd5) begin
                next_state <= 3'd2;
                count <= 3'd2;
            end

            if (ped && state == 3'd1) begin
                next_state <= 3'd2;
                count <= 3'd2;
            end

            state <= next_state;
            count <= count - 1;

            if (count == 3'd0) begin
                if (next_state == 3'd0) begin
                    light <= 2'b00;
                    walk <= 1'b1;
                end else if (next_state == 3'd1) begin
                    light <= 2'b01;
                    walk <= 1'b0;
                end else if (next_state == 3'd2) begin
                    light <= 2'b10;
                    walk <= 1'b0;
                end
            end
        end
    end

endmodule

