module traffic_light (
    input clk,
    input reset,
    input ped,
    output reg [1:0] light,
    output reg walk
);

    reg [2:0] state;
    reg [2:0] next_state;
    reg [3:0] count;

    always @(posedge clk) begin
        if (reset) begin
            state <= 3'd0;
            count <= 4'd0;
            light <= 2'b00;
            walk <= 1'b1;
        end else begin
            if (state == 3'd0) begin
                if (ped) begin
                    next_state <= 3'd0;
                    count <= 4'd0;
                end else begin
                    next_state <= 3'd0;
                    count <= 4'd0;
                end
            end else if (state == 3'd1) begin
                if (count == 3'd3) begin
                    next_state <= 3'd2;
                    count <= 4'd0;
                end else begin
                    next_state <= state;
                    count <= count + 1;
                end
            end else if (state == 3'd2) begin
                if (count == 3'd4) begin
                    next_state <= 3'd3;
                    count <= 4'd0;
                end else begin
                    next_state <= state;
                    count <= count + 1;
                end
            end else if (state == 3'd3) begin
                if (count == 3'd2) begin
                    next_state <= 3'd0;
                    count <= 4'd0;
                end else begin
                    next_state <= state;
                    count <= count + 1;
                end
            end
        end
    end

    always @(posedge clk) begin
        if (reset) begin
            state <= 3'd0;
            count <= 4'd0;
        end else begin
            state <= next_state;
        end
    end

    always @(posedge clk) begin
        if (reset) begin
            count <= 4'd0;
        end else begin
            if (state == 3'd0) begin
                count <= 4'd0;
            end else if (state == 3'd1) begin
                if (count < 3'd3) begin
                    count <= count + 1;
                end
            end else if (state == 3'd2) begin
                if (count < 3'd4) begin
                    count <= count + 1;
                end
            end else if (state == 3'd3) begin
                if (count < 3'd2) begin
                    count <= count + 1;
                end
            end
        end
    end

    always @(posedge clk) begin
        if (reset) begin
            light <= 2'b00;
            walk <= 1'b1;
        end else begin
            case (state)
                3'd0: begin
                    light <= 2'b00;
                    walk <= 1'b1;
                end
                3'd1: begin
                    light <= 2'b01;
                    walk <= 1'b0;
                end
                3'd2: begin
                    light <= 2'b10;
                    walk <= 1'b0;
                end
                3'd3: begin
                    light <= 2'b00;
                    walk <= 1'b1;
                end
            endcase
        end
    end

endmodule

